const { REACT_APP_GETUSER_URL, REACT_APP_APPCUES_ENABLED_URL } = process.env;
const APP_CONTAINER = document.getElementById("SS-DashboardWrapper");

// axios.defaults.baseURL = 'http://localhost:3000';
